import { betterAuth } from 'better-auth';

// The Drizzle schema (generated by @better-auth/cli) names columns in snake_case; BetterAuth's Kysely path looks
// columns up by its camelCase field names. `fields` maps each model field to the real column.
const snake = (s) => s.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`);
const map = (names) => Object.fromEntries(names.map((n) => [n, snake(n)]));

// BetterAuth on its Kysely path over a pg Pool (or the routing pool). No Drizzle adapter at runtime.
export function createAuth(pool, opts = {}) {
  return betterAuth({
    database: pool,
    secret: process.env.BETTER_AUTH_SECRET,
    baseURL: 'http://localhost:3000',
    emailAndPassword: { enabled: true, requireEmailVerification: false },
    user: { fields: map(['emailVerified', 'createdAt', 'updatedAt']) },
    session: { fields: map(['expiresAt', 'createdAt', 'updatedAt', 'ipAddress', 'userAgent', 'userId']) },
    account: { fields: map(['accountId', 'providerId', 'userId', 'accessToken', 'refreshToken', 'idToken', 'accessTokenExpiresAt', 'refreshTokenExpiresAt', 'createdAt', 'updatedAt']) },
    verification: { fields: map(['expiresAt', 'createdAt', 'updatedAt']) },
    ...(opts.userCreateAfter ? { databaseHooks: { user: { create: { after: opts.userCreateAfter } } } } : {}),
  });
}
